// Neon Void Escape – minimal canvas game
// Canvas element with id="game" must exist in the host HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth;
  const height = canvas.height = canvas.clientHeight;

  // Ship state
  const ship = {
    x: width / 2,
    y: height * 0.8,
    angle: -Math.PI / 2,
    radius: 8,
    vx: 0,
    vy: 0,
    thrust: 0.05,
    rotateSpeed: 0.07,
  };

  // Obstacles array
  const obstacles = [];
  let obstacleTimer = 0;
  const obstacleInterval = 90; // frames
  let score = 0;
  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  function spawnObstacle() {
    const size = Math.random() * 30 + 15;
    const x = Math.random() * (width - size) + size / 2;
    const speed = Math.random() * 1.5 + 0.5;
    obstacles.push({ x, y: -size, size, speed });
  }

  function update() {
    if (gameOver) return;
    // Controls
    if (keys['ArrowLeft'] || keys['a']) ship.angle -= ship.rotateSpeed;
    if (keys['ArrowRight'] || keys['d']) ship.angle += ship.rotateSpeed;
    if (keys['ArrowUp'] || keys['w']) {
      ship.vx += Math.cos(ship.angle) * ship.thrust;
      ship.vy += Math.sin(ship.angle) * ship.thrust;
    }
    // Apply velocity & wrap
    ship.x += ship.vx;
    ship.y += ship.vy;
    // simple friction
    ship.vx *= 0.99;
    ship.vy *= 0.99;
    // Keep ship within canvas (wrap horizontally, bounce vertically)
    if (ship.x < 0) ship.x += width;
    if (ship.x > width) ship.x -= width;
    if (ship.y < 0) ship.y = 0, ship.vy = 0;
    if (ship.y > height) ship.y = height, ship.vy = 0;

    // Obstacles
    obstacleTimer++;
    if (obstacleTimer >= obstacleInterval) {
      obstacleTimer = 0;
      spawnObstacle();
    }
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.y += o.speed;
      // Remove off‑screen
      if (o.y - o.size > height) {
        obstacles.splice(i, 1);
        score++;
        continue;
      }
      // Collision detection (circle‑rect approximation)
      const dx = Math.abs(ship.x - o.x);
      const dy = Math.abs(ship.y - o.y);
      if (dx < o.size / 2 + ship.radius && dy < o.size / 2 + ship.radius) {
        gameOver = true;
      }
    }
  }

  function draw() {
    // Clear with dark background
    ctx.fillStyle = '#0a0a0a';
    ctx.fillRect(0, 0, width, height);

    // Draw ship (neon triangle)
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(10, 0);
    ctx.lineTo(-8, -6);
    ctx.lineTo(-8, 6);
    ctx.closePath();
    ctx.fillStyle = '#00ffff';
    ctx.fill();
    ctx.restore();

    // Draw obstacles (neon squares)
    ctx.fillStyle = '#ff00ff';
    obstacles.forEach(o => {
      ctx.fillRect(o.x - o.size / 2, o.y - o.size / 2, o.size, o.size);
    });

    // Score
    ctx.fillStyle = '#ffffff';
    ctx.font = '16px monospace';
    ctx.fillText(`Score: ${score}`, 10, 20);

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#ff5555';
      ctx.font = '32px monospace';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Start the loop
  requestAnimationFrame(loop);
})();
